// Parse and validate Supabase operation request
const request = $input.first().json;

// Validate required fields
const requiredFields = ['operation', 'table', 'data'];
const missingFields = requiredFields.filter(field => !request[field]);

if (missingFields.length > 0) {
  return [{
    json: {
      error: true,
      message: `Missing required fields: ${missingFields.join(', ')}`,
      statusCode: 400
    }
  }];
}

// Validate operation type
const validOperations = [
  'insert',
  'update',
  'delete',
  'select',
  'upsert',
  'batch_insert',
  'batch_update',
  'batch_delete'
];

if (!validOperations.includes(request.operation)) {
  return [{
    json: {
      error: true,
      message: `Invalid operation: ${request.operation}. Valid operations: ${validOperations.join(', ')}`,
      statusCode: 400
    }
  }];
}

// Validate table access permissions
const allowedTables = [
  'alex_ai_memories',
  'alex_ai_memory_embeddings',
  'alex_ai_memory_relationships',
  'alex_ai_crew_activities',
  'alex_ai_project_configs',
  'alex_ai_sync_status',
  'alex_ai_security_audits'
];

if (!allowedTables.includes(request.table)) {
  return [{
    json: {
      error: true,
      message: `Access denied to table: ${request.table}. Allowed tables: ${allowedTables.join(', ')}`,
      statusCode: 403
    }
  }];
}

// Add security context
const securityContext = {
  requestId: `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  timestamp: new Date().toISOString(),
  source: request.source || 'alex-ai-universal',
  userId: request.userId || 'system',
  sessionId: request.sessionId || 'default'
};

// Return validated request
return [{
  json: {
    error: false,
    operation: request.operation,
    table: request.table,
    data: request.data,
    filters: request.filters || {},
    options: request.options || {},
    securityContext: securityContext,
    validated: true
  }
}];

// Route to appropriate Supabase operation based on operation type
const request = $input.first().json;
const operation = request.operation;

// Route to different operation handlers
switch (operation) {
  case 'insert':
  case 'upsert':
    return [{ json: { ...request, routeTo: 'insert-operation' } }];

  case 'update':
    return [{ json: { ...request, routeTo: 'update-operation' } }];

  case 'delete':
    return [{ json: { ...request, routeTo: 'delete-operation' } }];

  case 'select':
    return [{ json: { ...request, routeTo: 'select-operation' } }];

  case 'batch_insert':
  case 'batch_update':
  case 'batch_delete':
    return [{ json: { ...request, routeTo: 'batch-operation' } }];

  default:
    return [{ json: { ...request, routeTo: 'unknown-operation' } }];
}

// Execute Supabase INSERT/UPSERT operation
const request = $input.first().json;
const { table, data, options } = request;

// Simulate Supabase operation (replace with actual Supabase client call)
const operation = request.operation === 'upsert' ? 'upsert' : 'insert';

// Add audit trail
const auditData = {
  operation: operation,
  table: table,
  data: data,
  timestamp: new Date().toISOString(),
  requestId: request.securityContext.requestId,
  source: request.securityContext.source
};

// Log operation for security audit
console.log(`🔒 Supabase ${operation} operation:`, auditData);

// Simulate successful operation
const result = {
  success: true,
  operation: operation,
  table: table,
  affected_rows: Array.isArray(data) ? data.length : 1,
  data: data,
  audit: auditData,
  timestamp: new Date().toISOString()
};

return [{ json: result }];

// Execute Supabase UPDATE operation
const request = $input.first().json;
const { table, data, filters } = request;

// Add audit trail
const auditData = {
  operation: 'update',
  table: table,
  data: data,
  filters: filters,
  timestamp: new Date().toISOString(),
  requestId: request.securityContext.requestId,
  source: request.securityContext.source
};

// Log operation for security audit
console.log('🔒 Supabase update operation:', auditData);

// Simulate successful operation
const result = {
  success: true,
  operation: 'update',
  table: table,
  affected_rows: 1,
  data: data,
  filters: filters,
  audit: auditData,
  timestamp: new Date().toISOString()
};

return [{ json: result }];

// Execute Supabase DELETE operation
const request = $input.first().json;
const { table, filters } = request;

// Add audit trail
const auditData = {
  operation: 'delete',
  table: table,
  filters: filters,
  timestamp: new Date().toISOString(),
  requestId: request.securityContext.requestId,
  source: request.securityContext.source
};

// Log operation for security audit
console.log('🔒 Supabase delete operation:', auditData);

// Simulate successful operation
const result = {
  success: true,
  operation: 'delete',
  table: table,
  affected_rows: 1,
  filters: filters,
  audit: auditData,
  timestamp: new Date().toISOString()
};

return [{ json: result }];

// Execute Supabase SELECT operation
const request = $input.first().json;
const { table, filters, options } = request;

// Add audit trail
const auditData = {
  operation: 'select',
  table: table,
  filters: filters,
  options: options,
  timestamp: new Date().toISOString(),
  requestId: request.securityContext.requestId,
  source: request.securityContext.source
};

// Log operation for security audit
console.log('🔒 Supabase select operation:', auditData);

// Simulate successful operation with mock data
const mockData = {
  id: 1,
  content: 'Sample data from Supabase',
  created_at: new Date().toISOString(),
  updated_at: new Date().toISOString()
};

const result = {
  success: true,
  operation: 'select',
  table: table,
  data: [mockData],
  count: 1,
  filters: filters,
  options: options,
  audit: auditData,
  timestamp: new Date().toISOString()
};

return [{ json: result }];

// Execute Supabase BATCH operations
const request = $input.first().json;
const { operation, table, data } = request;

// Add audit trail
const auditData = {
  operation: operation,
  table: table,
  data: data,
  batch_size: Array.isArray(data) ? data.length : 0,
  timestamp: new Date().toISOString(),
  requestId: request.securityContext.requestId,
  source: request.securityContext.source
};

// Log operation for security audit
console.log(`🔒 Supabase ${operation} operation:`, auditData);

// Simulate successful batch operation
const result = {
  success: true,
  operation: operation,
  table: table,
  affected_rows: Array.isArray(data) ? data.length : 0,
  data: data,
  audit: auditData,
  timestamp: new Date().toISOString()
};

return [{ json: result }];

// Format final response with security audit trail
const result = $input.first().json;

// Add comprehensive response metadata
const response = {
  success: result.success,
  operation: result.operation,
  table: result.table,
  result: result.data || null,
  metadata: {
    affected_rows: result.affected_rows || 0,
    timestamp: result.timestamp,
    requestId: result.audit.requestId,
    source: result.audit.source
  },
  security: {
    audit_trail: result.audit,
    compliance: 'PRIME_DIRECTIVE_ENFORCED',
    data_protection: 'ENABLED'
  },
  n8n_workflow: {
    name: 'Alex AI - Supabase Middleware Layer',
    version: '1.0.0',
    execution_id: `exec_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
  }
};

return [{ json: response }];
